// The historic-link corpus (pack 07 section 5.4: "a harvested set of historic links, which every build must open").
//
// Harvested once from the repo's own tests and docs, and written out here so it does not move when they do: each entry names
// where it was found. It is not a file under parity/corpus/ (that path needs the owner's attest); it is generated by code, and
// tests/parity/links.test.mjs pins its digest, so changing a link, adding one or dropping one fails a test.
//
// Three kinds of entry:
//   hash   a URL hash, as a shared link or a page's "back to the selection" link carries it (the compact keys x c u s p ...).
//          Written as the object the link encoded; the text is encodeURIComponent(JSON.stringify(object)), exactly as toHash
//          writes it. A damaged hash is a raw string.
//   file   a saved scenario (JSON text), the version 1 and version 2 shapes, and the ones a build must refuse.
//   read   a saved scenario that lives in a docs file; its bytes are pinned by sha256, so an edited file fails loudly.
//
// `expect` is what the OLD decoder does with it today (a test holds that): opened, empty (no hash at all) or refused.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { canon } from './canon.ts';
import { REPO_ROOT } from './engine-copy.ts';
import type { LinkRequest } from './types.ts';
import { sha256Hex } from './util.ts';

export interface HistoricLink {
  id: string;
  kind: 'hash' | 'file';
  /** The text the decoder receives, or null when it is read from `read`. */
  text: string | null;
  /** A docs file whose bytes are the text, with the sha256 they must still have. */
  read: { path: string; sha256: string } | null;
  expect: 'opened' | 'empty' | 'refused';
  /** Where it was found. */
  source: string;
  note: string;
}

const hash = (id: string, source: string, expect: HistoricLink['expect'], payload: object | string, note = ''): HistoricLink => ({
  id, kind: 'hash', text: typeof payload === 'string' ? payload : encodeURIComponent(JSON.stringify(payload)), read: null, expect, source, note,
});
const file = (id: string, source: string, expect: HistoricLink['expect'], payload: object | string, note = ''): HistoricLink => ({
  id, kind: 'file', text: typeof payload === 'string' ? payload : JSON.stringify(payload), read: null, expect, source, note,
});
const docFile = (id: string, path: string, sha256: string): HistoricLink => ({
  id, kind: 'file', text: null, read: { path, sha256 }, expect: 'opened', source: path, note: 'a saved version 2 scenario from the 2026-10-18 screening review',
});

