interface TemplateLike {
  name: string;
  constraints: object[];
}

const slug = (s: string): string => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

/**
 * Every landing-page template as the two link shapes a page has written: version 1 (no x) and version 2 (x:2), in Explore.
 * The templates come from the old app, so a template that changes shows as a new link text and fails the digest test.
 */
function templateLinks(templates: readonly TemplateLike[]): HistoricLink[] {
  return templates.flatMap((t) => [
    hash(`hash/template-v1/${slug(t.name)}`, 'app/js/ui/templates.js (version 1 key shape: c, u)', 'opened', { c: t.constraints, u: 'exploration' }, `${t.name}, as a version 1 link`),
    hash(`hash/template-v2/${slug(t.name)}`, 'app/js/ui/templates.js (version 2 key shape: x, c, u, s, t, l, e, k)', 'opened',
      { x: 2, c: t.constraints, u: 'exploration', s: [], t: t.name, l: 'table', e: true, k: 'properties', b: null, m: null }, `${t.name}, as a version 2 link`),
  ]);
}

/** The whole harvested corpus: the literals found in tests and docs, then the templates' links. */
export function historicLinks(templates: readonly TemplateLike[]): HistoricLink[] {
  const all = [...FOUND, ...templateLinks(templates)];
  const ids = new Set(all.map((l) => l.id));
  if (ids.size !== all.length) throw new Error('historic links: duplicate id');
  return all;
}

/** The text of a link, reading and checking a docs file when the link lives in one. Throws, naming the file, when its bytes moved. */
export function linkRequest(link: HistoricLink): LinkRequest {
  if (link.text !== null) return { kind: link.kind, text: link.text };
  if (!link.read) throw new Error(`historic link ${link.id} has neither text nor a file`);
  const bytes = readFileSync(join(REPO_ROOT, link.read.path));
  const got = sha256Hex(bytes);
  if (got !== link.read.sha256) {
    throw new Error(`historic link ${link.id}: ${link.read.path} changed (sha256 ${got.slice(0, 12)}, pinned ${link.read.sha256.slice(0, 12)}); re-harvest it in packages/parity/src/historic-links.ts`);
  }
  return { kind: link.kind, text: bytes.toString('utf8') };
}

/** sha256 over the corpus definition (ids, kinds, texts or file pins, expectations): what tests/parity/links.test.mjs pins. */
export const digestOfLinks = (links: readonly HistoricLink[]): string =>
  `sha256:${sha256Hex(canon(links.map((l) => [l.id, l.kind, l.text, l.read, l.expect])))}`;

/**
 * The distinct hashes the built material pages link back to the selector with (`../H2C_Material_Selector_<stamp>.html#<hash>`):
 * a page of this release is itself a historic link for the next one. Only links to the selector count (an in-page anchor such as
 * `M001.html#sources` is not a scenario). Found in the pages the caller already read, in sorted order, each once.
 */
export function hashesInPages(pages: ReadonlyMap<string, string>): string[] {
  const found = new Set<string>();
  for (const html of pages.values()) {
    for (const m of html.matchAll(/href="[^"#]*H2C_Material_Selector_[^"#]*\.html#([^"]+)"/g)) {
      const fragment = m[1];
      if (fragment !== undefined) found.add(fragment);
    }
  }
  return [...found].sort();
}
